-- Crystal FM pay calendar 2026 (January – December), one row per project per month. 336 rows.
-- Paste into Supabase > SQL Editor > New query > Run  (run the v4.8 schema.sql first). Safe to run again: it updates the same rows.
on conflict (stream, period, row_key) do update set year = excluded.year, period_month = excluded.period_month, pay_group = excluded.pay_group, project_name = excluded.project_name,
  reconcile_from = excluded.reconcile_from, reconcile_to = excluded.reconcile_to, validation_date = excluded.validation_date, pay_date = excluded.pay_date, updated_at = now();
